import { expect, test } from 'bun:test';
import { renderToStaticMarkup } from 'react-dom/server';
import { AppRouterContext, type AppRouterInstance } from 'next/dist/shared/lib/app-router-context.shared-runtime.js';
import { seedServedTypes } from './apps/web/features/catalogue/type-fixtures.ts';
import { workExperience } from './apps/web/features/entity-page/experience.ts';
import { shelfVerb } from './apps/web/features/work-page/shelf-words.ts';
import { workReportTargets } from './apps/web/features/work-page/work-report-targets.ts';
import { WorkSources } from './apps/web/features/work-page/work-sources.tsx';
import { work, workRef } from './apps/web/features/work-page/fixtures.ts';
import { statements } from './apps/web/features/entity-page/fixtures.ts';
import { messages } from './apps/web/features/work-page/messages.ts';

seedServedTypes();
const router: AppRouterInstance = { bfcacheId: '', refresh() {}, push() {}, replace() {}, back() {}, forward() {}, prefetch() {} };

test('known Recipe retains its type and cook shelf verb when projection is unavailable', () => {
  const experience = workExperience(null, ['https://schema.org/Recipe']);
  expect({ kind: experience.kind, shelf: shelfVerb(experience), typeSection: experience.typeSection })
    .toEqual({ kind: 'recipe', shelf: 'cook', typeSection: null });
});

test('control: Book fallback retains its book task and reading shelf', () => {
  const experience = workExperience(null, ['https://schema.org/Book']);
  expect({ kind: experience.kind, shelf: shelfVerb(experience) }).toEqual({ kind: 'book', shelf: 'read' });
});

test('control: synopsis report keeps the rendered metadata revision', () => {
  const report = workReportTargets(work, workRef).find(target => target.kind === 'text');
  expect(report?.target).toBe(work.id);
  expect(report?.selection?.revision).toBe(work.metadataRevision);
});

test('page-end evidence exposes the field locator and quote actually supplied by its owner', () => {
  const page = statements();
  const item = page.groups[0]!.items[0]!;
  if (item.kind !== 'statement') throw new Error('Expected statement fixture');
  item.sources = ['https://rezics.com/id/00000000-0000-4000-8000-000000000042'];
  item.evidence = [{ id: item.sources[0]!, sourceWork: work.id,
    representationSha256: 'a'.repeat(64), locator: { pointer: '/characters/0/name' },
    quote: 'Kirito is the retained character name', quoteWithheld: false,
    method: { kind: 'source-excerpt' }, modality: 'text', submitter: work.id, rightsBasis: 'public-domain' }];
  const html = renderToStaticMarkup(<AppRouterContext.Provider value={router}>
    <WorkSources work={work} locale="en" messages={messages.en}
      statements={{ ok: true, data: page }} />
  </AppRouterContext.Provider>);
  expect(html).toContain('/characters/0/name');
  expect(html).toContain('Kirito is the retained character name');
});

